public class TrafficLight {
    private String color = "Red";

    public String getColor() {
        return color;
    }

    public boolean isStopRequired() {
        return color.equals("Red") || color.equals("Yellow");
    }

    public void advance() {
        if (color.equals("Red")) {
            color = "Green";
        } else if (color.equals("Green")) {
            color = "Yellow";
        } else {
            color = "Red";
        }
    }
}
